"""Original micro-literature with genuine personal responses and bounded comparison checks."""
import json
from pathlib import Path
items=[]
def base(bank,q):
 n=sum(x['bank']==bank for x in items)+1
 return dict(id=f'AC9E3LE02-{bank[0].upper()}-{n:03d}',subject='english',year_level='Year 3',curriculum_code='AC9E3LE02',bank=bank,skill='Personal connections and literary preferences',question=q,audio_prompt=q,visual={'type':'none'},source={'creator':'SkillrHub original literary microtext'})
def mc(bank,text,ask,c,ws,why):
 x=base(bank,text+'\n\n'+ask);p=sum(i['bank']==bank and i.get('grading_mode')!='adult-review' for i in items)%4;opts=ws[:];opts.insert(p,c);x.update(answers=[{'text':t,'is_correct':j==p} for j,t in enumerate(opts)],correct_index=p,explanation={'summary':why,'hint':'Compare the experience or preference with the actual story detail.'});items.append(x)
def task(bank,text,ask,model,note):
 x=base(bank,text+'\n\n'+ask);x.update(grading_mode='adult-review',answers=[],correct_index=None,model_answer=model,acceptance_note=note+' Accept different experiences and preferences when the connection is explained. Do not treat the model opinion as the only correct response.',response_instructions='Share your response with a partner or adult, or write two or three sentences. An adult checks the connection to the supplied story. Use an everyday experience you are comfortable discussing.',completion_label='I shared my response aloud; an adult still needs to check it.',explanation={'summary':model,'hint':'Name a detail from the story and explain how it connects with your response.'});items.append(x)
mc('practice','Story: Tia’s tower fell. She took a breath and built a wider base. / Reader: “That reminds me of fixing my paper plane after it would not fly.”','What connects these experiences?','Trying a change after something did not work.',['Both characters are building towers.','Both give up without another attempt.','Both win a flying competition.'],'The objects differ, but both experiences involve revising an unsuccessful attempt.')
mc('practice','Story: Ollie waved at the new child and moved his bag to make room. / Reader: “I liked that moment because it made the newcomer feel included.”','Which story detail supports the preference?','Ollie makes room for the new child.',['Ollie takes the new child’s lunch.','The newcomer wins a prize.','The teacher gives Ollie a new bag.'],'Making space is the supplied welcoming action; the other events are not in the story.')
mc('practice','Story: Rain cancelled Noor’s picnic. She spread the blanket on the lounge-room floor instead. / Reader: “My outdoor game was cancelled, but we invented an indoor one.”','Which connection is supported?','Both find another plan after weather changes their activity.',['Both have exactly the same picnic food.','Both refuse to play indoors.','Both know the weather forecast was wrong.'],'The shared experience is adjusting the plan, not identical activities or food.')
mc('practice','Story A: A snail followed a silver trail to a secret garden. / Story B: A child searched for a missing library book. / Reader: “I prefer mysteries about ordinary life.”','Which preference fits the reader’s stated reason?','B, because searching for a missing book is an everyday mystery.',['A, because both stories are about missing books.','B, because it has a talking snail.','A, because it contains no unusual setting.'],'B supplies the everyday search; the other descriptions misstate the extracts.')
mc('practice','Story: Leo waited quietly while his friend finished explaining the rules. / Reader: “I know how it feels to wait when I am excited to start.”','How can this be a connection even if the reader played a different game?','The feeling and waiting situation can be similar.',['A connection requires the same game name.','The reader must be Leo’s friend in the story.','The story proves every reader feels excited.'],'Connections can concern similar feelings or situations without being identical events.')
mc('practice','Story: Amira returned a dropped coin to its owner. / Reader: “I prefer this ending because she chooses to help someone.”','What makes the reason text-based?','It refers to the act of returning the coin.',['It says Amira buys a bicycle.','It says the owner is Amira’s teacher.','It guesses the coin is worth a thousand dollars.'],'The preference is supported by the actual helpful action, not an invented event or value.')
mc('practice','Story: A nervous bird tried singing one note, then another. / Reader: “I have never been a bird, but practising a new song felt similar.”','What is the meaningful link?','Learning to sing a little at a time.',['The reader has feathers.','The bird is practising mathematics.','Both have already performed the same concert.'],'The learning experience supplies the connection; literal identity with the character is unnecessary.')
mc('practice','Story: Kit chose the winding path because it passed a pond. / Reader: “I would choose the short path because I like arriving quickly.”','Does the reader have to share Kit’s preference?','No; a different preference can be explained with a reason.',['Yes; every reader must choose the pond path.','Yes; the story bans short paths.','No; the reader can change what Kit actually chose.'],'A reader can disagree with a character’s choice while accurately recognising it.')
mc('practice','Story: Max’s friend moved to a different classroom, so they arranged to meet at lunch. / Reader: “My friend and I also make a plan when we cannot spend the morning together.”','Which detail is the connection based on?','Arranging another time to meet.',['Both friends move to a different country.','Neither friend wants to meet again.','Both have lunch in the same named classroom.'],'The supplied common action is making a plan to keep meeting; the other claims add unsupported facts.')
mc('practice','Poem: Warm light in the window, / My boots by the door. / Reader: “These lines remind me of coming home after a long walk.”','Which words most directly support the link?','The window light and boots by the door.',['A noisy football crowd that is not mentioned.','A train timetable that is not mentioned.','A character winning a swimming race.'],'The domestic arrival details support the reader’s personal association.')
mc('practice','Story A ends with the lost kitten returning home. Story B ends before the kitten is found. / Reader: “I like knowing how a problem is solved.”','Which ending would best match that stated preference?','A, because the kitten’s return resolves the search.',['B, because it tells us exactly where the kitten lives.','Both, because neither leaves a question open.','Neither, because both kittens are still lost.'],'A supplies resolution; B deliberately leaves the outcome open.')
mc('practice','Story: A child shares her last piece of chalk with a friend. / Reader: “This reminds me of sharing my coloured pencils.”','Which statement keeps the similarity and difference accurate?','Both involve sharing drawing materials, but the materials differ.',['Both involve sharing chalk.','The child in the story shares coloured pencils.','Neither involves another person.'],'Chalk and pencils are different materials used for drawing, so the connection is similar rather than identical.')
practice='''Mila practised tying a knot. It slipped twice, but the third knot held her small kite string.|Connect Mila’s attempts with a time you practised an everyday skill. Explain a similarity or difference.|Learning a new fold took me several tries too. Unlike Mila, I was using paper rather than string.|Look for a practising/retrying connection and one accurate story detail; a different experience can be contrasted.
A boy found an empty seat beside him on the bus. He moved his backpack so his friend could sit down.|What do you think of the boy’s action? Connect your response to a time someone made room for another person.|I like his action because moving the bag welcomes his friend. It reminds me of making space at a shared table.|Require an opinion about the supplied action and an explained everyday connection, not the same example.
The little boat waited at the shore. When the wind arrived, it bobbed away with a leaf for a sail.|Which part of this short story appeals to you most, and why?|I like the leaf sail because it turns an ordinary leaf into part of a tiny adventure.|Accept any chosen detail, or a explained lack of preference, with a reason that fits the text.
Jai planned to draw a dragon, but a splash of paint became a bright cloud. He added a small dragon flying through it.|Relate Jai’s change of plan to something that turned out differently from your first idea.|My model had an extra piece, so I turned it into a lookout. Like Jai, I used the unexpected part.|Check the unexpected-change connection; do not require the outcome to be described as positive.
Story A: A puppy stole a sock and fell asleep with it. Story B: A puppy followed footprints to find a missing toy.|Which opening would you choose to read on from? Explain your preference using a detail.|I choose B because the footprints make me wonder where the toy went.|Either preference is valid; require an actual feature from the chosen opening.
Nina waited beside the oven while the bread cooled. The smell made the waiting seem longer.|Compare Nina’s waiting with waiting for something you looked forward to.|I have waited for a game to start. I felt eager like Nina, but there was no bread smell.|Look for a feeling or situation connection and an accurate distinction if offered.
Poem: Mud on my shoes, / Rain on my nose, / Home is a towel / And warm, dry toes.|Which image in the poem reminds you of something familiar? Explain the connection.|The towel reminds me of drying off after being outdoors in rain.|Accept any supported sensory or event connection; no need for an identical rainy experience.
A shy robot had a bell instead of a voice. It rang once to ask for help, and a child stopped to listen.|Would you like to read more about this robot? Give a reason based on this introduction.|Yes, because I want to know how the child understands the robot’s bell.|Yes or no can be justified; require reference to the communication situation or another supplied detail.
Sam offered to show a friend how to fold a paper bird. When the friend found a different fold, Sam tried that one too.|Connect this exchange with a time you learned from someone after first trying to help them.|I showed someone a game and they found a new strategy. We both learned, like Sam and the friend.|Look for two-way learning or a explained contrast; do not claim Sam rejects the friend’s idea.
A rabbit in a waistcoat checked a tiny timetable. “Late for the carrot train again!” it cried.|Which detail makes this character interesting or uninteresting to you? Explain why.|The carrot train interests me because I wonder what that make-believe journey is like.|Accept a different reaction with the waistcoat, timetable or train as evidence; taste in stories is not a fixed key.
Elsa had to choose one shell to take home. She left the largest and chose a small one shaped like a heart.|Compare Elsa’s reason for choosing with something you value in a keepsake.|I might choose the heart shape too because its shape would remind me of the day, rather than choosing the largest.|The text does not explicitly state Elsa’s full feelings; distinguish her observed choice from the reader’s own reason.
Two endings: A—The friends repaired the bridge together. B—The bridge remained broken, but they found another path.|Which ending do you prefer? Explain how its solution affects your response.|I prefer B because finding a new path is an unexpected way to solve the problem.|Either solution can be preferred; require accurate reference to repair versus an alternative route.
A child watered a seed every morning. One day a green tip pushed through the soil, and she called her brother to look.|Connect the child’s discovery with noticing progress in something you have done or watched.|Seeing a drawing improve after practice felt exciting to me, like noticing the new shoot.|Accept progress/discovery connections; do not require gardening experience or invent what the brother says.
The old umbrella grumbled about sunny days. “No adventures for me,” it sighed from the cupboard.|Do you enjoy giving ordinary objects feelings in a story? Use this umbrella to explain your view.|I enjoy it because the umbrella’s complaint makes me imagine a cupboard full of bored objects.|Positive, negative or mixed preferences are valid if tied to the person-like complaint.
Ari brought a puzzle to share. Nobody solved it at first, so each person offered one small clue.|Relate the group’s approach to solving something with others.|When we could not finish a game, each person suggested one move. Small ideas helped us make progress too.|Look for cooperation or shared contributions and an accurate story detail.
Poem A: Bang went the lid, and away rolled the spoon! Poem B: A soft little moon watched a sleepy lagoon.|Which line would you choose for a quiet reading, and do you enjoy that kind of poem?|B suits quiet reading because soft and sleepy sound calm. I prefer calm poems at bedtime.|Separate the supported quiet-reading choice from the learner’s personal preference, which can differ.
Rani’s friend chose a different team. Rani looked disappointed, then waved to wish her luck.|How does this moment connect with having a different choice from a friend?|I have chosen a different game from a friend. We could still be friendly, like Rani waving.|Accept a comfortable everyday difference or a contrast; do not demand disclosure of a difficult friendship event.
A tiny door appeared in the trunk of the classroom tree. Behind it someone was playing a very small violin.|What would make you want—or not want—to continue reading? Refer to the opening.|I want to continue because I wonder who is playing behind the tiny door.|Accept curiosity, disinterest or another reaction supported by the unusual door/music; no invented answer to the mystery is needed.'''
for line in practice.splitlines():task('practice',*line.split('|'))
more='''Omar packed a picnic carefully, then discovered he had forgotten the cups. His sister offered to fetch them.|Connect Omar’s forgotten item and his sister’s help with an everyday experience.|I once forgot pencils for drawing and someone lent me one. Both situations involve help with a missing item.|Accept a similar incident or a difference; do not require embarrassment or blame as the feeling.
Story A: A fox outsmarted a locked gate. Story B: A fox asked another animal to help open it.|Which kind of solution do you prefer in a story, and why?|I prefer B because I enjoy seeing characters solve problems together.|Either is acceptable; connect the reason to independent cleverness or asking for help, without inventing how the gate opens.
The first time Bea read her poem aloud, her voice was small. The next time, she looked up and spoke more clearly.|Compare Bea’s change with becoming more comfortable at something.|I became more comfortable explaining a game after trying it a few times. Bea also seems more confident on a later attempt.|Require a link to growing comfort/practice; accept a different experience and avoid demanding public-speaking experience.
Poem: A single yellow leaf / Came floating to my knee; / The tree had sent a letter, / Or so it seemed to me.|What do you like or dislike about the leaf-as-letter idea?|I like it because it makes an ordinary falling leaf feel like a special message.|Accept different reactions supported by the comparison, not a claim that the tree literally writes letters.
A child saved the last piece of ribbon for a friend’s model. Later the friend brought an extra button for hers.|Connect the exchange with giving and receiving help or materials.|It reminds me of sharing paper and later borrowing a marker. Help can go both ways.|Look for reciprocal sharing or an explained contrast; not all connections must have the same materials.
A sailor followed a map to an island and found not treasure, but a garden of enormous flowers.|Would you enjoy this unexpected ending? Explain your reaction.|I would enjoy it because the flowers surprise me after expecting treasure.|Positive or negative reactions are valid if the treasure/flower change is accurate.
Tess hurried to finish her painting. She stopped when she noticed that slowly adding one colour made the picture clearer.|Relate Tess’s change of pace to something you prefer doing carefully.|I like placing small model pieces slowly so they fit. That connects with Tess finding care more useful than rushing.|Accept a different preference about pace with a clear contrast; do not require the view that slow is always best.
Poem A: The train raced on with a rattling roar. Poem B: The train crept softly past the shore.|Which train description do you prefer to hear aloud? Explain your choice.|I like A because the rattling roar gives me a strong sound to imagine.|Either can be preferred; use fast/loud versus slow/soft evidence, not an unstated journey destination.
Jules wanted to play alone for a while. Her friend nodded and said they could meet later.|How does this connect with wanting quiet time or choosing when to join others?|Sometimes I enjoy reading alone before joining a game. Jules also asks for time apart without ending the friendship.|Accept a similar preference or a contrast; the story does not say the friend is angry.
A detective searched the whole house for a missing spoon. It was tucked inside the very hat she was wearing.|Do you find the solution funny, surprising or neither? Explain why.|I find it funny because the detective searches everywhere while carrying the spoon herself.|Accept another reaction if linked to the hat discovery; no requirement to laugh.
A child learned a new skipping pattern by watching a friend, then trying it slowly.|Connect the way the child learns with a way you like learning something new.|I like watching someone make a fold before trying it. Both involve seeing an example first.|Accept observing, asking, reading or another method with a similarity or difference explained.
The dragon could breathe only bubbles. Instead of guarding treasure, it became the village’s favourite bubble maker.|Would you choose a gentle dragon like this or a fierce dragon in a story? Give a reason.|I would choose this dragon because using an unusual ability to make people happy interests me.|Either preference is valid; refer to the supplied bubbles/role rather than inventing a fierce dragon’s events.
A busker’s song reminded Lila of a tune her grandfather hummed while cooking. She paused to listen.|Share how a sound, smell or object can remind you of an everyday moment, and link it to Lila’s response.|The smell of toast reminds me of breakfast at home. A familiar sound brings Lila a memory in the same way.|Accept any comfortable everyday association; no family disclosure is required and the sense can differ.
Story A finishes with a clear answer to every clue. Story B leaves one small clue unexplained.|Which style of ending do you prefer, and how does it affect your interest?|I prefer one clue left open because it gives me something to wonder about afterwards.|Accept either or a mixed preference, linked to resolution or continuing curiosity.
Finn had planned to walk with one friend, but a new classmate asked to join. Finn slowed down so all three could talk.|Connect Finn’s adjustment with including someone in an activity.|We changed the space in a game so another person could join. Finn also changes what he is doing to include someone.|Look for an inclusion-related connection or contrast and the actual slowing down detail.
Poem: The night folded the town / Into pockets of light.|Which word or image would you mention when telling someone your opinion of these lines?|I would mention pockets of light because it makes me picture small bright windows in a dark town.|Accept any explained interpretation/opinion grounded in the words; windows are a possible imagined image, not a stated fact.
A character chooses to take an unfamiliar route home because she hopes to see something new.|Would you make the same choice in an ordinary safe setting? Compare your preference with hers.|I might choose the familiar route because I like knowing where I am going, unlike her wish to explore.|The comparison can agree or differ; no instruction to take an unsafe route or disclose actual location.
Two story openings: A—The key hummed inside the drawer. B—The team practised its last pass before the match.|Choose an opening and explain how it connects with the kinds of activities or stories you enjoy.|I choose B because I enjoy team games and want to know whether their practice helps.|Accept either interest link, with the actual key or team detail as evidence.'''
for line in more.splitlines():task('practice',*line.split('|'))
mc('test','Story: Dana’s model boat sank. She removed some weight and tried again. / Reader: “I changed my paper glider when it kept dropping.”','What is the supported connection?','Both improve a design after an unsuccessful attempt.',['Both build boats.','Both stop trying immediately.','Both know the same design will always win.'],'Boat and glider differ, but changing a design after a failed attempt is shared.')
mc('test','Story A ends when the friends find the missing map. Story B ends just as they notice a strange mark on a wall. / Reader: “I enjoy being left with a puzzle.”','Which choice matches that preference?','B, because its ending opens a new question.',['A, because the map is still missing.','Both, because neither ends with an event.','B, because it explains every mystery.'],'The unexplained mark leaves a puzzle, while A resolves the map search.')
mc('test','Story: A small creature sings alone, then welcomes another voice. / Reader: “I liked joining a group song after practising on my own.”','Which detail supports the connection?','Moving from singing alone to singing with someone.',['Both singers have the same name.','The creature refuses to share the song.','The reader lives inside the story.'],'The shared progression in participation supports the link without requiring identical characters.')
mc('test','Poem: A warm mug waited beside the window. / Reader: “This reminds me of a cosy afternoon watching rain.”','How should this response be understood?','It is a personal association supported by the warm indoor image.',['It proves that the poem explicitly says rain is falling.','It means every reader must remember the same afternoon.','It changes the mug into an outdoor river.'],'The reader may connect the image with a memory without claiming every part of that memory appears in the poem.')
tests='''A child offered a new game to the group. When one player suggested changing a rule, she listened and tried the change.|Connect the character’s openness to a time you considered another person’s idea.|I changed a drawing after someone suggested a different background. Both involve trying someone else’s idea.|Require a relevant similarity or difference, not the same activity or automatic agreement.
Story A: A turtle solves a problem slowly and carefully. Story B: A hare solves a different problem with a sudden clever idea.|Which kind of problem-solving story appeals to you, and why?|I enjoy the turtle’s kind because I like following careful steps.|Either character approach can be preferred; do not assume one always succeeds better from these summaries.
Poem: Wet leaves on the path, / A bright scarf at my chin, / The first cool breeze of morning / As our walk begins.|Choose a detail that connects with an everyday experience and explain the link.|The bright scarf reminds me of getting ready for a cool morning outing.|Accept a supported sensory or event connection; the learner need not have worn a scarf.
A character practises a small part of a song instead of trying the whole song at once.|Compare that approach with how you like tackling a difficult task.|I also like doing one small section first when a task seems difficult.|Accept agreement or a explained different strategy with the small-part approach accurately recognised.
A magic cupboard opens onto a different garden each day, but it never opens when anyone is watching.|Would this idea make you want to keep reading? Explain your preference.|Yes, because I want to know how the character will see the gardens if the door will not open while watched.|Either reaction is valid; the reason should refer to the unusual rule or changing gardens.
A child spends time helping a friend finish a model and then finishes her own work later.|How does this connect with balancing your own task and helping someone else?|I have had to decide when to pause my work to explain a game. The character also makes time for someone else.|Accept a neutral everyday comparison; do not prescribe always putting someone else’s work first.
Poem A: Quiet stars above the hill. Poem B: Clattering wheels and a whistle shrill.|Which sound or mood would you choose for a poem to enjoy, and why?|I prefer the quiet mood of A because it feels restful to me.|A preference for either is valid; connect it to quiet or the active/loud wording.
A friend in a story makes a mistake in a game, laughs gently at himself and asks to try again.|Relate one part of this reaction to a way you respond to everyday mistakes.|I often want another try too, although I do not always laugh straight away.|Accept differences in emotion; require an accurate detail and do not demand a cheerful reaction.
Two endings: A—The traveller stays in the new town. B—The traveller returns home with a story to tell.|Which ending would you prefer, and how does it connect with what you enjoy in stories or everyday life?|I prefer returning home because I enjoy stories where characters share what they discovered.|Either ending is acceptable; require the chosen ending to remain accurately described.
A character makes a gift from spare bits of paper because she cannot find the ribbon she wanted.|Compare her use of available materials with making or doing something using what you had.|I once used scrap card for a model when I had no new sheet. Like her, I used what was available.|Look for resourcefulness or a clear contrast; no financial disclosure is needed.
A talking cloud keeps forgetting where it has left its rain. It asks a kite to help search.|What part of this premise shapes your personal response to it?|The forgetful cloud interests me because losing rain is a funny impossible problem.|Accept positive, negative or mixed reactions supported by cloud/rain/kite details.
A character watches someone complete a tricky puzzle, then asks to hear how they chose the first step.|Connect this with a question you might ask when learning from someone, and explain why that question helps you.|I might ask how they knew where to begin, because the first step often helps me understand the rest.|Require a learning-related question and explanation connected to the character asking about the first step.'''
for line in tests.splitlines():task('test',*line.split('|'))
assert len(items)==64,len(items)
assert sum(i['bank']=='practice' for i in items)==48
# The story states a choice, not a complete account of Elsa's motive.
for x in items:
 x['question']=x['question'].replace('Compare Elsa’s reason for choosing with','Compare Elsa’s choice with')
 x['audio_prompt']=x['question']
Path(__file__).with_name('ac9e3le02.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print('LE02: 64 original tasks; 48 personal responses and 16 supported connection checks.')
